"""Schraudolph-style fast log₂ for IEEE 754 float64.

Spec: docs/spf-formats-and-test-plans.md §11.3.

The method reinterprets a positive-normal float64's bit pattern as an int64 and
recovers log₂(x) by subtracting the IEEE 754 bias, using the identity

    (x as int64) / 2⁵² = exponent_unbiased + mantissa_fraction

and approximating log₂(1 + mantissa_fraction) by the mantissa fraction itself
(Mitchell) plus a minimax polynomial correction. Purely integer/FMA operations
— no transcendentals — which is the point for the eventual C port's encode hot
path.

Two variants are exported:

* ``fast_log2_mitchell``: the raw bit-cast with *no* correction. Max absolute
  error ≤ 0.0861 in log₂(x). This is the form written in spec §11.3.
* ``fast_log2``: bit-cast plus a degree-4 minimax polynomial on the mantissa
  fraction. Max absolute error ≤ 2⁻¹² ≈ 2.4e-4 in log₂(x), which survives Q7.8
  rounding (ULP = 2⁻⁸). This is the form wired into encode().

**Encode-path only.** Never use inside Sb(). The L values entering Sb are
exact Q7.8 integers; introducing approximation error there poisons the error
envelope that the LUT + cancellation-wedge fallback is calibrated against.

Domain: positive normals. Zero, subnormals, inf, and NaN are detected by the
encode path and routed to sentinel handling before fast_log2 is called.
"""

from __future__ import annotations

import numpy as np
import numpy.typing as npt

from spf.native._lib import LIBSPF_AVAILABLE

if LIBSPF_AVAILABLE:
    from spf.native import spf32 as _c_spf32
else:
    _c_spf32 = None  # type: ignore[assignment]

__all__ = [
    "MITCHELL_MAX_ABS_ERROR",
    "POLY_MAX_ABS_ERROR",
    "fast_log2",
    "fast_log2_magnitude",
    "fast_log2_mitchell",
]

# ── IEEE 754 float64 layout constants ────────────────────────────────────────
_BIAS: int = 1023
_MANTISSA_BITS: int = 52
_MANTISSA_SCALE: float = float(1 << _MANTISSA_BITS)
_INV_MANTISSA_SCALE: float = 1.0 / _MANTISSA_SCALE

# ── Minimax polynomial for log₂(1+m) on m ∈ [0, 1) ──────────────────────────
#
# Generated by Remez-style minimax fit (coefficients below were produced offline
# with scipy.signal.remez-equivalent iteration; the test_fast_log meta-test
# re-derives and checks them each run, so drift is caught). Written in Horner
# form as:
#
#   log₂(1+m) ≈ m + m·(1−m)·(c0 + c1·m + c2·m² + c3·m³)
#
# The (1−m) factor pins the endpoints (log₂(1)=0, log₂(2)=1 → m + m(1−m)·p(m)
# with m+m(1−m)p(m) = m at m=0 and = 1 at m=1), so the polynomial only has to
# fit the interior curvature.
_POLY_COEFFS: tuple[float, float, float, float] = (
    0.44245399645543254,
    -0.2701589482926353,
    0.1520193721568402,
    -0.045841030812957644,
)

# ── Published error envelopes (validated by test_fast_log.py) ───────────────
MITCHELL_MAX_ABS_ERROR: float = 0.0861  # |log₂(1+m) - m|_max at m ≈ 0.4427
POLY_MAX_ABS_ERROR: float = 1.0e-4  # measured max over [0, 1) Chebyshev-fit grid


def _raw_bitcast(x: npt.NDArray[np.float64]) -> npt.NDArray[np.float64]:
    """Reinterpret positive-normal float64 bits as int64, scale to exp+mant_frac."""
    bits = x.view(np.int64)
    return bits.astype(np.float64) * _INV_MANTISSA_SCALE - _BIAS


def fast_log2_mitchell(x: npt.ArrayLike) -> npt.NDArray[np.float64]:
    """Bit-cast log₂ with no correction (spec §11.3 form).

    Max absolute error ≈ 0.0861 in log₂(x). Not used by encode — retained as
    the reference the C port will compile to before any polynomial correction
    is applied.
    """
    x_arr = np.asarray(x, dtype=np.float64)
    return _raw_bitcast(x_arr)


def fast_log2(x: npt.ArrayLike) -> npt.NDArray[np.float64]:
    """Bit-cast log₂ with minimax polynomial correction on the mantissa.

    Routes through the C ``spf32_fast_log2_array`` entry point when libspf32
    is available; falls back to the pure-numpy implementation otherwise.

    Max absolute error ≤ 2⁻¹¹ in log₂(x), verified in tests/scalar/test_fast_log.py.
    Operates on positive normals only; callers must route zero/subnormal/inf/
    NaN through sentinel logic.
    """
    if _c_spf32 is not None:
        arr = np.asarray(x, dtype=np.float64)
        out = _c_spf32.fast_log2(arr)
        return out.reshape(arr.shape)

    return _fast_log2_numpy(x)


def _fast_log2_numpy(x: npt.ArrayLike) -> npt.NDArray[np.float64]:
    """Pure-numpy fallback for hosts without libspf32."""
    x_arr = np.asarray(x, dtype=np.float64)
    bits = x_arr.view(np.int64)

    # exponent_unbiased = int(bits >> 52) - 1023; mantissa_frac = mantissa_bits / 2^52.
    exponent = ((bits >> _MANTISSA_BITS) & 0x7FF).astype(np.int64) - _BIAS
    mantissa_bits = (bits & ((1 << _MANTISSA_BITS) - 1)).astype(np.float64)
    m = mantissa_bits * _INV_MANTISSA_SCALE

    # Horner evaluation of c0 + c1·m + c2·m² + c3·m³.
    c0, c1, c2, c3 = _POLY_COEFFS
    poly = c0 + m * (c1 + m * (c2 + m * c3))

    return exponent.astype(np.float64) + m + m * (1.0 - m) * poly


def fast_log2_magnitude(
    re: npt.ArrayLike, im: npt.ArrayLike
) -> npt.NDArray[np.float64]:
    """log₂(|z|) via fast_log2(|z|²) / 2; saves one sqrt per element."""
    re_arr = np.asarray(re, dtype=np.float64)
    im_arr = np.asarray(im, dtype=np.float64)
    r2 = re_arr * re_arr + im_arr * im_arr
    return fast_log2(r2) * 0.5
